#include "virtual_broadcast/broadcaster/channel.hpp"
#include "virtual_broadcast/broadcaster/named_pipe_server.hpp"
#include "virtual_broadcast/bondriver/pipe_client.hpp"
#include "virtual_broadcast/common/runtime_config.hpp"
#include <cassert>
#include <chrono>
#include <filesystem>
#include <fstream>
#include <thread>
namespace {template<class F>bool Throws(F f){try{f();return false;}catch(...){return true;}}vb::VirtualChannel Channel(std::uint32_t i){vb::VirtualChannel c;c.channel_index=i;c.name="Virtual "+std::to_string(i);c.si.service_name=i==0?"松山自主放送":i==1?"松山自主放送2":"テスト放送";c.ts_name=c.si.service_name;c.udp_port=static_cast<std::uint16_t>(12340+i);c.remote_control_key_id=static_cast<std::uint8_t>(8+i);c.physical_channel=static_cast<std::uint8_t>(20+i);c.center_frequency_hz=515142857+6000000ull*i;c.ids={32760,32760,static_cast<std::uint16_t>(32513+i),static_cast<std::uint16_t>(101+i),static_cast<std::uint16_t>(0x8001+i),static_cast<std::uint16_t>(1+i)};c.si.original_network_id=c.ids.original_network_id;c.si.network_id=c.ids.network_id;c.si.transport_stream_id=c.ids.transport_stream_id;c.si.service_id=c.ids.service_id;c.si.remote_control_key_id=c.remote_control_key_id;c.si.ts_name=c.ts_name;c.si.epg.interval_minutes=i==0?60:i==1?120:1440;c.si.logo.enabled=true;c.si.logo.source=std::filesystem::path(VB_SOURCE_DIR)/"config/sample-logo.png";c.si.logo.logo_id=c.ids.logo_id;c.si.logo.download_data_id=c.ids.download_data_id;return c;}}
int main(){
  const auto loaded=vb::LoadRuntimeConfig(std::filesystem::path(VB_SOURCE_DIR)/"config/multi-channel-example.toml");assert(loaded.channels.size()==3&&loaded.channels[0].si.service_name=="松山自主放送"&&loaded.channels[1].si.epg.interval_minutes==120&&loaded.channels[2].remote_control_key_id==10);
  std::vector<vb::VirtualChannel>channels{Channel(0),Channel(1),Channel(2)};vb::ChannelManager manager(channels);assert(manager.EnumerateChannels().size()==3&&manager.GetChannel(0,2)->ids.service_id==103&&!manager.GetChannel(1,0));
  const auto a=vb::IdManager::Generate("stable virtual channel"),b=vb::IdManager::Generate("stable virtual channel");assert(a.original_network_id==b.original_network_id&&a.transport_stream_id==b.transport_stream_id&&a.service_id==b.service_id&&a.download_data_id==b.download_data_id);
  auto bad=channels;bad[1].ids.transport_stream_id=bad[0].ids.transport_stream_id;assert(Throws([&]{vb::IdManager::Validate(bad);}));bad=channels;bad[1].ids.service_id=bad[0].ids.service_id;bad[1].ids.transport_stream_id=bad[0].ids.transport_stream_id;assert(Throws([&]{vb::IdManager::Validate(bad);}));bad=channels;bad[1].ids.download_data_id=bad[0].ids.download_data_id;assert(Throws([&]{vb::IdManager::Validate(bad);}));
  for(auto key:{1,8,12}){auto x=Channel(0);x.remote_control_key_id=key;vb::IdManager::Validate(std::span<const vb::VirtualChannel>(&x,1));}for(auto key:{0,13,255}){auto x=Channel(0);x.remote_control_key_id=static_cast<std::uint8_t>(key);assert(Throws([&]{vb::IdManager::Validate(std::span<const vb::VirtualChannel>(&x,1));}));}
  vb::AribStringEncoder encoder;for(const auto&c:channels){const auto nit=vb::NitGenerator::Generate(c.si,encoder);const auto network_len=((nit[8]&15)<<8)|nit[9],loop=10+network_len,desc=loop+8;assert(nit[desc]==vb::kDescriptorServiceList);const auto info=desc+5;assert(nit[info]==vb::kDescriptorTsInformation&&nit[info+2]==c.remote_control_key_id);}
  std::vector<vb::pipe::ChannelInfo>wire;for(const auto&c:channels)wire.push_back({0,c.channel_index,c.ids.service_id,c.ids.transport_stream_id,c.remote_control_key_id,c.physical_channel,c.center_frequency_hz,c.signal_level,c.si.service_name});const auto encoded=vb::pipe::EncodeChannels(wire);std::vector<vb::pipe::ChannelInfo>decoded;assert(vb::pipe::DecodeChannels(encoded,decoded)&&decoded.size()==3&&decoded[1].name=="松山自主放送2"&&decoded[1].center_frequency_hz==521142857);
  const auto json=std::filesystem::temp_directory_path()/"vb-existing-ids.json";{std::ofstream f(json);f<<"[{\"original_network_id\":32760,\"transport_stream_id\":32513,\"service_id\":101,\"download_data_id\":32769}]";}const auto existing=vb::IdManager::LoadExistingJson(json);std::filesystem::remove(json);assert(existing.size()==1&&Throws([&]{vb::IdManager::Validate(channels,existing);}));const auto avoided=vb::IdManager::Generate("stable virtual channel",existing);assert(!(avoided.original_network_id==32760&&avoided.transport_stream_id==32513));
  const auto suffix=std::to_wstring(GetCurrentProcessId());vb::NamedPipeServer server(L"VBM6Control"+suffix,L"VBM6Ts"+suffix,wire);assert(server.Start());std::this_thread::sleep_for(std::chrono::milliseconds(100));vb::TsRingBuffer ring_a(188*32),ring_b(188*32);vb::PipeClient client_a(L"VBM6Control"+suffix,L"VBM6Ts"+suffix,ring_a),client_b(L"VBM6Control"+suffix,L"VBM6Ts"+suffix,ring_b);assert(client_a.Open()&&client_b.Open());std::vector<vb::pipe::ChannelInfo>enumerated;assert(client_a.EnumerateChannels(enumerated)&&enumerated.size()==3);assert(client_a.SetChannel(0)&&client_b.SetChannel(1));vb::TsPacket pa{},pb{};pa[0]=pb[0]=0x47;pa[1]=0;pa[2]=0x30;pb[1]=0;pb[2]=0x31;server.Broadcast(0,pa);server.Broadcast(1,pb);std::this_thread::sleep_for(std::chrono::milliseconds(150));std::array<std::uint8_t,188>out{};assert(ring_a.Read(out)==188&&out[2]==0x30);assert(ring_b.Read(out)==188&&out[2]==0x31);assert(client_a.SetChannel(2)&&ring_a.PacketCount()==0);client_a.Close();client_b.Close();server.Stop();
  return 0;
}
